<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Mini Spreadsheet</title>
<style>
  body{font-family:sans-serif;margin:20px;}
  table{border-collapse:collapse; width:auto; min-width:600px;}
  th,td{border:1px solid #999;padding:0; text-align:center;}
  th{background:#eee;font-weight:bold;}
  input{width:80px;height:25px;border:none;text-align:right; padding-right:5px;}
  input:focus{outline:2px solid blue;background:#f0f8ff;}
  textarea{margin-top:10px;width:100%;height:200px;}
</style>
</head>
<body>

<table id="grid"></table>
<button id="export">Export CSV</button><br>
<textarea id="csv" readonly></textarea>

<script>
// Build grid
const cols='ABCDEFGHIJ';
const rows=Array.from({length:10},(_,i)=>i+1);
const table=document.getElementById('grid');
const cellMap={};
for(let r of rows){
  const tr=document.createElement('tr');
  for(let c of cols){
    const td=document.createElement('td');
    const id=`cell-${c}${r}`;
    const inp=document.createElement('input');
    inp.id=id;
    inp.value='';
    inp.dataset.row=r; inp.dataset.col=c;
    inp.addEventListener('focus',e=>{inp.value=inp.dataset.raw||'';});
    inp.addEventListener('blur',commit);
    inp.addEventListener('keydown',(e)=>{if(e.key==='Enter'){inp.blur();}});
    td.appendChild(inp);
    tr.appendChild(td);
    cellMap[id]=inp;
  }
  table.appendChild(tr);
}
// Header row
const headerRow=document.createElement('tr');
headerRow.appendChild(document.createElement('th'));
for(let c of cols){let th=document.createElement('th');th.textContent=c;headerRow.appendChild(th);}
table.insertBefore(headerRow,table.firstChild);

// Dependency graph
const dependents={}; // cellId -> set of cells that depend on it
function addDep(src,dst){
  if(!dependents[src]) dependents[src]=new Set();
  dependents[src].add(dst);
}
function clearDeps(cellId){
  for(let src in dependents){dependents[src]?.delete(cellId);}
}

// Evaluate cell
function evalCell(id,stack=[]) {
  const inp=cellMap[id];
  const raw=inp.dataset.raw||'';
  if(raw.startsWith('=')){
    // cycle detection
    if(stack.includes(id)) return '#CYCLE';
    stack.push(id);
    const expr=raw.slice(1).trim();
    try{
      const value=parseExpr(expr,stack);
      inp.dataset.value=value;
      return value.toString();
    }catch(e){
      if(e.message==='CYCLE') return '#CYCLE';
      return '#ERR';
    }
  }else{
    // plain text
    const val=raw.trim()===''?0:raw;
    inp.dataset.value=val;
    return val;
  }
}

// Simple parser (shunting yard)
function parseExpr(expr,stack){
  const tokens=[];
  let i=0;
  while(i<expr.length){
    const ch=expr[i];
    if(/\s/.test(ch)){i++;continue;}
    if(/[+\-*/()]/.test(ch)){
      tokens.push(ch); i++;
    }else if(/[A-Ja-j][1-9]0?/.test(expr.slice(i))){
      let m=expr.slice(i).match(/^([A-Ja-j])([1-9]\d?)$/);
      const ref=`cell-${m[1].toUpperCase()}${m[2]}`;
      if(!cellMap[ref]) throw new Error('ERR');
      // ensure referenced cell evaluated
      addDep(ref,stack[stack.length-1]); // current cell depends on ref
      tokens.push(evalCell(ref,stack));
      i+=m[0].length;
    }else if(/\d/.test(ch)){
      let num='';
      while(i<expr.length && /\d/.test(expr[i])){num+=expr[i++];}
      tokens.push(Number(num));
    }else{
      throw new Error('ERR');
    }
  }
  // convert to RPN
  const output=[];
  const ops=[];
  const prec={'+':1,'-':1,'*':2,'/':2};
  for(let tok of tokens){
    if(typeof tok==='number' || !isNaN(tok)) {output.push(Number(tok));}
    else if(['+','-','*','/'].includes(tok)){
      while(ops.length && prec[ops[ops.length-1]]>=prec[tok]) output.push(ops.pop());
      ops.push(tok);
    }else if(tok==='('){ops.push(tok);}
    else if(tok===')'){
      while(ops.length && ops[ops.length-1]!='(') output.push(ops.pop());
      ops.pop();
    }
  }
  while(ops.length) output.push(ops.pop());
  // evaluate RPN
  const stackEval=[];
  for(let token of output){
    if(typeof token==='number'){stackEval.push(token);}
    else{
      const b=stackEval.pop(), a=stackEval.pop();
      let res;
      switch(token){case '+':res=a+b;break;case '-':res=a-b;break;
        case '*':res=a*b;break;case '/':res=a/b;break;}
      stackEval.push(res);
    }
  }
  if(stackEval.length!==1) throw new Error('ERR');
  return stackEval[0];
}

function commit(e){
  const inp=e.target;
  const id=inp.id;
  clearDeps(id);
  inp.dataset.raw=inp.value.trim();
  recomputeFrom(id);
}

function recomputeFrom(changedId){
  // BFS over dependents
  const queue=[changedId];
  const visited=new Set();
  while(queue.length){
    const cur=queue.shift();
    if(visited.has(cur)) continue;
    visited.add(cur);
    evalCell(cur);
    const deps=dependents[cur];
    if(deps){deps.forEach(d=>queue.push(d));}
  }
}

document.getElementById('export').addEventListener('click',()=>{
  let csv='';
  for(let r of rows){
    let row=[];
    for(let c of cols){
      const val=cellMap[`cell-${c}${r}`].dataset.value||'';
      row.push(val);
    }
    csv+=row.join(',')+'\n';
  }
  document.getElementById('csv').value=csv;
});

// API
window.sheet={
  set:(cell,txt)=>{
    const inp=cellMap[`cell-${cell.toUpperCase()}`];
    if(!inp) return;
    inp.value=txt;
    inp.dataset.raw=txt.trim();
    clearDeps(inp.id);
    recomputeFrom(inp.id);
  },
  get:(cell)=>{
    const inp=cellMap[`cell-${cell.toUpperCase()}`];
    return inp?inp.dataset.value||'':'';
  },
  raw:(cell)=>{
    const inp=cellMap[`cell-${cell.toUpperCase()}`];
    return inp?inp.dataset.raw||'':'';
  }
};
</script>
</body>
</html>
